from __future__ import annotations

from dataclasses import dataclass
from typing import Final, Literal

import numpy as np
import polars as pl
from numpy.typing import NDArray
from scipy.sparse import csr_array

SeqType = Literal["AA", "NT"]
NormMode = Literal["none", "log", "Neg", "logNeg"]
DeviceType = Literal["auto", "cuda", "cpu"]
CompositionMode = Literal["binary", "count"]

DEFAULT_SEED: Final[int] = 647474747
DEFAULT_VERSION: Final[str] = "SWeeP v2.9"


@dataclass(slots=True, frozen=True)
class OrthBaseResult:
    """Represents the projection basis matrix generated by orth_base."""

    mat: NDArray[np.float64]
    seed: int = DEFAULT_SEED
    version: str = DEFAULT_VERSION


@dataclass(slots=True, frozen=True)
class SweepInfo:
    """Detailed metadata about the SWeeP projection process."""

    projection_size: int
    bin: str
    norm: NormMode
    version: str
    time_elapsed: float
    headers: list[str] | None = None
    mask: NDArray[np.int32] | None = None
    sequence_type: SeqType | None = None
    extension: str | list[str] | None = None
    concatenate: bool | None = None
    transpose: bool | None = None
    rna_seq_data: bool | None = None
    features: list[str] | None = None
    samples: list[str] | None = None


@dataclass(slots=True, frozen=True)
class SweepResult:
    """Standard output of sweep and sweep_lite projection functions."""

    proj: NDArray[np.float64]
    info: SweepInfo


@dataclass(slots=True, frozen=True)
class HDVInfo:
    """Detailed metadata about the High Dimensional Vector (HDV) extraction."""

    headers: list[str] | None
    mask: NDArray[np.int32]
    sequence_type: SeqType
    extension: str | list[str]
    concatenate: bool
    bin: str
    version: str
    saturation: NDArray[np.float64] | float
    time_elapsed: float


@dataclass(slots=True, frozen=True)
class HDVResult:
    """Output of extract_hdv, maintaining strictly sparse CSR storage."""

    hdv: csr_array
    info: HDVInfo


@dataclass(slots=True, frozen=True)
class PCCIResult:
    """Result of PhyloTaxonomic Consistency Cophenetic Index (PCCI) evaluation."""

    tab: pl.DataFrame
    mean: float


@dataclass(slots=True, frozen=True)
class PMPGResult:
    """Result of Percentage of Mono or Paraphyletic Groups (PMPG) evaluation."""

    tab: pl.DataFrame
    perc_mono: float
    perc_para: float
    metric: float
